package com.fataar.gradle

import org.gradle.api.GradleException
import org.objectweb.asm.ClassWriter
import org.objectweb.asm.Opcodes

/** Compile-only, non-final R symbols. Real IDs are generated by the consuming AGP. */
internal object CompileResourceStubs {
    fun generate(namespace: String, text: String): Map<String, ByteArray> {
        val prefix = namespace.replace('.', '/') + "/R"
        val groups = text.lineSequence().filter { it.isNotBlank() }.map { it.split(' ', limit = 4) }.toList()
        if (groups.any { it.size != 4 || it[0] !in setOf("int", "int[]") })
            throw GradleException("FATAAR_INVALID_SYMBOL: invalid merged R.txt")
        val outer = ClassWriter(0).apply { visit(Opcodes.V17, Opcodes.ACC_PUBLIC or Opcodes.ACC_FINAL, prefix, null, "java/lang/Object", null) }
        val result = sortedMapOf<String, ByteArray>()
        groups.groupBy { it[1] }.toSortedMap().forEach { (type, fields) ->
            val name = "$prefix\$$type"
            val flags = Opcodes.ACC_PUBLIC or Opcodes.ACC_STATIC or Opcodes.ACC_FINAL
            outer.visitInnerClass(name, prefix, type, flags)
            val inner = ClassWriter(0).apply {
                visit(Opcodes.V17, Opcodes.ACC_PUBLIC or Opcodes.ACC_FINAL, name, null, "java/lang/Object", null)
                visitInnerClass(name, prefix, type, flags)
                fields.forEach { field -> visitField(Opcodes.ACC_PUBLIC or Opcodes.ACC_STATIC,
                    field[2], if (field[0] == "int[]") "[I" else "I", null, null).visitEnd() }
                visitEnd()
            }
            result["$name.class"] = inner.toByteArray()
        }
        outer.visitEnd(); result["$prefix.class"] = outer.toByteArray()
        return result
    }
}
